import * as React from "react";
type ToastItem = { id: number; message: React.ReactNode; tone: "default" | "success" | "error" };
const listeners = new Set<(items: ToastItem[]) => void>(); let items: ToastItem[] = []; let nextId = 0;
function push(message: React.ReactNode, tone: ToastItem["tone"]) { const item={id:++nextId,message,tone}; items=[...items,item]; listeners.forEach((listener)=>listener(items)); setTimeout(()=>{items=items.filter((entry)=>entry.id!==item.id);listeners.forEach((listener)=>listener(items));},4500); }
export const toast = Object.assign((message: React.ReactNode)=>push(message,"default"), { success:(message: React.ReactNode)=>push(message,"success"), error:(message: React.ReactNode)=>push(message,"error") });
export function Toaster() { const [current,setCurrent]=React.useState(items); React.useEffect(()=>{listeners.add(setCurrent);return()=>{listeners.delete(setCurrent)}},[]); return <div className="pointer-events-none fixed inset-x-4 bottom-4 z-[100] flex flex-col items-end gap-2 sm:left-auto sm:w-96" aria-live="polite">{current.map((item)=><div key={item.id} className={["pointer-events-auto w-full rounded-lg border px-4 py-3 text-sm shadow-lg",item.tone==="error"?"border-destructive/40 bg-destructive/10 text-destructive":item.tone==="success"?"border-success/40 bg-success/10 text-success":"border-border bg-card text-card-foreground"].join(" ")}>{item.message}</div>)}</div>; }
